mod run_make_support {
    use std::process::Command;

    pub mod rfs {
        pub fn read_to_string(path: &str) -> String {
            std::fs::read_to_string(path).unwrap()
        }

        pub fn write(path: &str, data: impl AsRef<[u8]>) {
            std::fs::write(path, data).unwrap();
        }
    }

    pub struct Rustc(Command);
    pub struct Output(String);

    pub fn rustc() -> Rustc {
        Rustc(Command::new("rustc"))
    }

    pub fn run(name: &str) -> Output {
        Rustc(Command::new(format!("./{name}"))).run()
    }

    impl Rustc {
        pub fn arg(&mut self, arg: impl AsRef<std::ffi::OsStr>) -> &mut Self {
            self.0.arg(arg);
            self
        }
        pub fn env(&mut self, key: &str, val: &str) -> &mut Self {
            self.0.env(key, val);
            self
        }
        pub fn input(&mut self, name: &str) -> &mut Self {
            self.arg(name)
        }
        pub fn edition(&mut self, n: &str) -> &mut Self {
            self.arg(format!("--edition={n}"))
        }
        pub fn opt_level(&mut self, n: &str) -> &mut Self {
            self.arg(format!("-Copt-level={n}"))
        }
        pub fn incremental(&mut self, dir: impl AsRef<str>) -> &mut Self {
            self.arg(format!("-Cincremental={}", dir.as_ref()))
        }
        pub fn codegen_units(&mut self, n: usize) -> &mut Self {
            self.arg(format!("-Ccodegen-units={n}"))
        }
        pub fn crate_name(&mut self, name: &str) -> &mut Self {
            self.arg("--crate-name").arg(name)
        }
        pub fn crate_type(&mut self, ty: &str) -> &mut Self {
            self.arg("--crate-type").arg(ty)
        }
        pub fn extern_(&mut self, name: &str, path: &str) -> &mut Self {
            self.arg("--extern").arg(format!("{name}={path}"))
        }
        pub fn run(&mut self) -> Output {
            let result = self.0.output().unwrap();
            assert!(
                result.status.success(),
                "{:?}: {}",
                self.0,
                String::from_utf8_lossy(&result.stderr)
            );
            Output(String::from_utf8(result.stdout).unwrap())
        }
    }

    impl Output {
        pub fn stdout_utf8(self) -> String {
            self.0
        }
        pub fn assert_stdout_contains(self, text: &str) {
            assert!(self.0.contains(text), "{}", self.0)
        }
        pub fn assert_stdout_equals(self, text: String) {
            assert_eq!(self.0, text)
        }
    }
}

